extern "C" std::int64_t phonetic_alphabet_converter(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap) noexcept {static constexpr const char* words[36]={"Alpha", "Bravo", "Charlie", "Delta", "Echo", "Foxtrot", "Golf", "Hotel", "India", "Juliett", "Kilo", "Lima", "Mike", "November", "Oscar", "Papa", "Quebec", "Romeo", "Sierra", "Tango", "Uniform", "Victor", "Whiskey", "X-ray", "Yankee", "Zulu", "Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"};if(!v||n<1||n>65||v[0]<0||v[0]>64||n!=static_cast<std::size_t>(v[0])+1)return -1;if(!out||cap<576)return -2;std::size_t at=0;bool emitted=false;for(std::size_t i=0;i<static_cast<std::size_t>(v[0]);++i){auto z=v[i+1];if(z<0||z>127||!((z>=33&&z<=126)||z==9||z==10||z==11||z==12||z==13||z==32))return -1;int c=static_cast<int>(z);if(c==9||c==10||c==11||c==12||c==13||c==32)continue;if(c>='a'&&c<='z')c-=32;if(emitted)out[at++]=' ';emitted=true;const char*w=(c>='A'&&c<='Z')?words[c-'A']:(c>='0'&&c<='9')?words[26+c-'0']:nullptr;if(w){auto len=std::strlen(w);std::memcpy(out+at,w,len);at+=len;}else out[at++]=static_cast<std::uint8_t>(c);}return static_cast<std::int64_t>(at);}
